mod model;mod plan;mod bp;
use anyhow::{bail,ensure,Context,Result};use model::{Model,observations};use plan::{Plan,create,analyze,execute};use std::{collections::BTreeMap,env,fs,path::{Path,PathBuf},time::Instant};use tenferro_cpu::CpuEngine;use tenferro_einsum::TypedTensorEinsumExt;use tenferro_tensor::TypedTensor;
fn args()->Result<BTreeMap<String,String>>{let mut it=env::args().skip(1);let mut a=BTreeMap::new();while let Some(k)=it.next(){ensure!(k.starts_with("--"),"unexpected argument {k}");let v=it.next().context(format!("missing value for {k}"))?;ensure!(a.insert(k.clone(),v).is_none(),"repeated argument {k}");}for k in a.keys(){ensure!(["--model","--evidence","--out","--order","--seed","--plan","--analyze","--method","--damping","--tolerance","--max-sweeps","--query"].contains(&k.as_str()),"unknown argument {k}");}Ok(a)}
fn required<'a>(a:&'a BTreeMap<String,String>,k:&str)->Result<&'a str>{Ok(a.get(k).with_context(||format!("missing {k}"))?)}
fn save<T:serde::Serialize>(path:&Path,val:&T)->Result<()>{fs::write(path,serde_json::to_string_pretty(val)?)?;Ok(())}
fn self_checks()->Result<serde_json::Value>{let mut cpu=CpuEngine::serial();let a=TypedTensor::<f64>::from_vec_col_major(vec![2,2],vec![1.,3.,2.,4.])?;let b=TypedTensor::<f64>::from_vec_col_major(vec![2,2],vec![2.,1.,0.,2.])?;let product=[&a,&b].einsum("ij,jk->ik",&mut cpu)?;let got=product.as_slice()?;let target=[4.,10.,4.,8.];let maxerr=got.iter().zip(target).map(|(x,y)|(x-y).abs()).fold(0.,f64::max);let trace=[&a,&b].einsum("ij,ji->",&mut cpu)?.as_slice()?[0];let k=TypedTensor::<f64>::from_vec_col_major(vec![2,2],vec![0.5f64.exp(),(-0.5f64).exp(),(-0.5f64).exp(),0.5f64.exp()])?;let z=[&k,&k,&k].einsum("ij,jk,ki->",&mut cpu)?.as_slice()?[0];let mut exact=0.;for s in 0..8 {let x=if s&1==0{-1.}else{1.};let y=if s&2==0{-1.}else{1.};let z=if s&4==0{-1.}else{1.};exact+=(0.5f64*(x*y+y*z+z*x)).exp();}ensure!(maxerr<1e-12&&(trace-12.).abs()<1e-12&&(z-exact).abs()<1e-12,"matrix/Ising check failed");Ok(serde_json::json!({"matrix_col_major":got,"matrix_expected_col_major":target,"matrix_max_abs_error":maxerr,"trace":trace,"trace_expected":12.,"trace_abs_error":(trace-12.).abs(),"ising_contraction":z,"ising_enumeration":exact,"ising_abs_error":(z-exact).abs()}))}
fn main()->Result<()>{let a=args()?;let model=Model::load(Path::new(required(&a,"--model")?))?;let ename=required(&a,"--evidence")?;let obs=observations(ename,model.dims.len())?;let out=PathBuf::from(required(&a,"--out")?);fs::create_dir_all(&out)?;let method=a.get("--method").map(String::as_str).unwrap_or("exact");
 if method=="bp" {for k in ["--order","--seed","--plan","--analyze","--query"]{ensure!(!a.contains_key(k),"{k} not supported with BP");}let damp: f64=required(&a,"--damping")?.parse()?;let tol:f64=required(&a,"--tolerance")?.parse()?;let max:usize=required(&a,"--max-sweeps")?.parse()?;let run=bp::run(&model,&obs,damp,tol,max)?;for t in &run.trace{println!("sweep={} residual={:.12e} work={}",t.sweep,t.residual,t.cumulative_work);}let mut val=serde_json::to_value(&run)?;if model.dims.len()==8{let (_z,exact,_joint)=model.enumerate(&obs)?;let err=run.marginals.iter().zip(&exact).flat_map(|(a,b)|(0..2).map(move|i|(a[i]-b[i]).abs())).fold(0.,f64::max);val["exact_marginals"]=serde_json::to_value(exact)?;val["max_marginal_error"]=serde_json::json!(err);println!("maximum marginal error = {:.12e}",err);}save(&out.join("run.json"),&val)?;println!("sweeps={}, residual={:.12e}, converged={}",run.sweeps,run.residual,run.converged);return Ok(())}
 ensure!(method=="exact","method must be exact or bp");for k in ["--damping","--tolerance","--max-sweeps"]{ensure!(!a.contains_key(k),"{k} requires BP");}
 let flags=["--order","--plan","--analyze"].iter().filter(|x|a.contains_key(**x)).count();ensure!(flags<=1,"order, plan and analyze are mutually exclusive");let order=a.get("--order").map(String::as_str).unwrap_or("greedy");let seed=a.get("--seed").map(|x|x.parse::<u64>()).transpose()?;ensure!(!(seed.is_some()&&order=="greedy"),"seed is only allowed with random or treesa ordering");if order=="random"||order=="treesa"{ensure!(seed.is_some(),"{order} requires --seed");}
 let (factors,log_scalar)=model.condition(&obs)?;let start=Instant::now();let mut scalar_plan=if let Some(path)=a.get("--plan").or(a.get("--analyze")){let mut p:Plan=serde_json::from_str(&fs::read_to_string(path)?)?;analyze(&mut p)?;ensure!(p.query.is_empty(),"scalar plan expected");ensure!(p.input_scopes==factors.iter().map(|f|f.vars.clone()).collect::<Vec<_>>(),"model/evidence scopes differ from plan");p}else{create(&factors,vec![],order,seed)?};analyze(&mut scalar_plan)?;
 save(&out.join("order.json"),&scalar_plan)?;save(&out.join("complexity.json"),&serde_json::json!({"total_work":scalar_plan.total_work,"largest_tensor_entries":scalar_plan.largest_tensor,"largest_generated_entries":scalar_plan.largest_generated,"steps":scalar_plan.steps,"units":"one pair cost = product of dimensions in the union of input labels"}))?;
 if a.contains_key("--analyze"){println!("Analysis only: work={}, largest={}",scalar_plan.total_work,scalar_plan.largest_tensor);return Ok(())}
 let (scalar,scale)=execute(&factors,&scalar_plan,log_scalar)?;ensure!(scalar.data.len()==1,"expected scalar");let log_z=scalar.data[0].ln()+scale;let z=log_z.exp();let mut marg=BTreeMap::new();let queries:Vec<usize>=if let Some(q)=a.get("--query"){q.split(',').map(str::parse).collect::<std::result::Result<_,_>>()?}else if model.dims.len()==8{(0..8).collect()}else{bail!("large models require --query ids")};
 for &v in &queries {ensure!(v<model.dims.len(),"query id out of range");if let Some(&state)=obs.get(&v){let mut x=[0.,0.];x[state]=1.;marg.insert(v,x);continue}let mplan=create(&factors,vec![v],order,seed)?;save(&out.join(format!("query-{v}-order.json")),&mplan)?;let (f,_scale)=execute(&factors,&mplan,log_scalar)?;ensure!(f.vars==vec![v]&&f.data.len()==2,"invalid marginal shape");let s:f64=f.data.iter().sum();marg.insert(v,[f.data[0]/s,f.data[1]/s]);}
 let mut joint=None;let mut discrepancy=None;let mut checks=None;if model.dims.len()==8{let p=create(&factors,vec![1,3],order,seed)?;let (f,_)=execute(&factors,&p,log_scalar)?;ensure!(f.vars==vec![1,3]&&f.data.len()==4,"invalid joint shape");let sum:f64=f.data.iter().sum();let mat=[[f.data[0]/sum,f.data[1]/sum],[f.data[2]/sum,f.data[3]/sum]];let(ez,em,ej)=model.enumerate(&obs)?;let max_marg=marg.iter().map(|(&v,x)|(x[0]-em[v][0]).abs().max((x[1]-em[v][1]).abs())).fold(0.,f64::max);let max_joint=(0..2).flat_map(|i|(0..2).map(move|j|(mat[i][j]-ej[i][j]).abs())).fold(0.,f64::max);let rel=(z-ez).abs()/ez;discrepancy=Some(serde_json::json!({"enumeration_evidence":ez,"max_marginal_abs_error":max_marg,"max_joint_abs_error":max_joint,"evidence_relative_error":rel,"enumeration_marginals":em,"enumeration_joint":ej}));ensure!(max_marg<1e-10&&max_joint<1e-10&&rel<1e-10,"ASIA mismatch with enumeration");joint=Some(mat);checks=Some(self_checks()?);}
 let run=serde_json::json!({"method":"exact","model":a.get("--model"),"evidence":ename,"observations":obs,"evidence_mass":z,"log10_partition":log_z/std::f64::consts::LN_10,"marginals":marg,"joint_TL":joint,"comparison_with_enumeration":discrepancy,"self_checks":checks,"scalar_plan_work":scalar_plan.total_work,"scalar_plan_largest":scalar_plan.largest_tensor,"runtime_seconds":start.elapsed().as_secs_f64(),"query_ids":queries});save(&out.join("run.json"),&run)?;println!("evidence mass={:.16e}; log10 Z={:.16}; work={}, largest={}",z,log_z/std::f64::consts::LN_10,scalar_plan.total_work,scalar_plan.largest_tensor);println!("marginals={}",run["marginals"]);if let Some(d)=run.get("comparison_with_enumeration"){println!("enumeration comparison: {d}")}if let Some(c)=run.get("self_checks"){println!("matrix and Ising checks: {c}")}Ok(())}
